import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

minred_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor min_reduce(torch::Tensor x, int64_t dim);
"""

minred_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

__device__ __forceinline__ float rmin(float a, float b) { return fminf(a, b); }

// Single fused reduction kernel.
// Collapsed 3D view of the contiguous input:
//   X[o, r, i]  ->  Y[o, i] = min over r of X[o, r, i]
// where O = prod(sizes before dim), R = size(dim), I = prod(sizes after dim).
// Consecutive threads map to consecutive i, so every iteration of the
// reduction loop is a fully coalesced global load.
template <typename T>
__global__ void min_reduce_kernel(const T* __restrict__ X,
                                  T* __restrict__ Y,
                                  int O, int R, int I)
{
  // CuTe global tensors with 64-bit strides for the large collapsed dims.
  Tensor mX = make_tensor(make_gmem_ptr(X),
                          make_shape(O, R, I),
                          make_stride((int64_t)R * I, (int64_t)I, Int<1>{}));
  Tensor mY = make_tensor(make_gmem_ptr(Y),
                          make_shape(O, I),
                          make_stride((int64_t)I, Int<1>{}));

  const int64_t total = (int64_t)O * I;
  const int64_t step  = (int64_t)gridDim.x * blockDim.x;

  for (int64_t out = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
       out < total; out += step) {
    int o = (int)(out / I);
    int i = (int)(out - (int64_t)o * I);

    // 4-way unrolled reduction with independent accumulators for ILP.
    T a0 = mX(o, 0, i);
    T a1 = a0;
    T a2 = a0;
    T a3 = a0;

    int r = 1;
    for (; r + 3 < R; r += 4) {
      a0 = rmin(a0, mX(o, r,     i));
      a1 = rmin(a1, mX(o, r + 1, i));
      a2 = rmin(a2, mX(o, r + 2, i));
      a3 = rmin(a3, mX(o, r + 3, i));
    }
    for (; r < R; ++r) {
      a0 = rmin(a0, mX(o, r, i));
    }

    mY(o, i) = rmin(rmin(a0, a1), rmin(a2, a3));
  }
}

torch::Tensor min_reduce(torch::Tensor x, int64_t dim) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.dim() == 3, "x must be 3D");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

  auto xc = x.contiguous();

  int64_t d = dim;
  if (d < 0) d += 3;
  TORCH_CHECK(d >= 0 && d < 3, "dim out of range for 3D input");

  int64_t O = 1, R = xc.size(d), I = 1;
  for (int64_t k = 0; k < d; ++k)     O *= xc.size(k);
  for (int64_t k = d + 1; k < 3; ++k) I *= xc.size(k);

  std::vector<int64_t> out_sizes;
  for (int64_t k = 0; k < 3; ++k) {
    if (k != d) out_sizes.push_back(xc.size(k));
  }
  auto y = torch::empty(out_sizes, xc.options());

  const int Threads = 256;
  const int64_t total = O * I;
  const int64_t blocks64 = (total + Threads - 1) / Threads;
  const unsigned blocks = (unsigned)std::min<int64_t>(blocks64, (int64_t)0x7fffffff);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  min_reduce_kernel<float><<<blocks, Threads, 0, stream>>>(
      xc.data_ptr<float>(),
      y.data_ptr<float>(),
      (int)O, (int)R, (int)I);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "min_reduce_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

minred_ext = load_inline(
    name="cute_min_reduce_ext",
    cpp_sources=minred_cpp_decl,
    cuda_sources=minred_cuda_src,
    functions=["min_reduce"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Min reduction over a specific dimension, implemented with a single
    custom CUDA kernel using CuTe tensors.
    """
    def __init__(self, dim: int):
        super().__init__()
        self.dim = int(dim)
        self._ext = minred_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.min_reduce(x, self.dim)

